def parse_map_file(filename):
    secciones = {
        "Habitaciones": [],
        "Arcos": [],
        "Enemigos": [],
        "Eventos": [],
        "Mejoras": []
    }
    seccion_actual = None

    with open(filename, "r", encoding="utf-8") as f:
        for linea in f:
            linea = linea.strip()
            if not linea or linea.startswith("#"):
                continue  # Saltar líneas vacías o comentarios

            if linea.startswith("[") and linea.endswith("]"):
                seccion_actual = linea[1:-1]
                continue

            if seccion_actual == "Habitaciones":
                # Ejemplo: 1|Sala de Inicio|Esta es la sala inicial.
                partes = linea.split("|")
                secciones["Habitaciones"].append({
                    "id": int(partes[0]),
                    "nombre": partes[1],
                    "descripcion": partes[2]
                })

            elif seccion_actual == "Arcos":
                # Ejemplo: 1|2
                origen, destino = map(int, linea.split("|"))
                secciones["Arcos"].append((origen, destino))

            elif seccion_actual == "Enemigos":
                # Ejemplo: 1|Pikachu|100|20|15|80|0.2
                partes = linea.split("|")
                secciones["Enemigos"].append({
                    "id": int(partes[0]),
                    "nombre": partes[1],
                    "vida": int(partes[2]),
                    "ataque": int(partes[3]),
                    "velocidad": int(partes[4]),
                    "precision": int(partes[5]),
                    "probabilidad": float(partes[6])
                })

            elif seccion_actual == "Eventos":
                # Ejemplo: 1|Encuentras una poción|A:Tomarla:+10 vida|B:Ignorarla:0
                partes = linea.split("|")
                opciones = {
                    "A": partes[2].split(":")[1:],
                    "B": partes[3].split(":")[1:]
                }
                secciones["Eventos"].append({
                    "id": int(partes[0]),
                    "descripcion": partes[1],
                    "opciones": opciones
                })

            elif seccion_actual == "Mejoras":
                # Ejemplo: 1|+5 ataque
                partes = linea.split("|")
                secciones["Mejoras"].append({
                    "id": int(partes[0]),
                    "mejora": partes[1]
                })

    return secciones

# Ejemplo de uso:
datos = parse_map_file("T2 v2.map")  # Cambia por el nombre real de tu archivo

# Construir el grafo del mapa
from collections import defaultdict

grafo = defaultdict(list)
for origen, destino in datos["Arcos"]:
    grafo[origen].append(destino)
    grafo[destino].append(origen)  # Si es bidireccional

# Ahora tienes:
# - datos["Habitaciones"]: lista de habitaciones
# - datos["Arcos"]: lista de conexiones
# - datos["Enemigos"]: lista de enemigos
# - datos["Eventos"]: lista de eventos
# - datos["Mejoras"]: lista de mejoras
# - grafo: estructura de conexiones entre habitaciones

# Puedes imprimir para verificar:
import pprint
pprint.pprint(datos)
pprint.pprint(dict(grafo))